import{_ as a,o as n,c as e,a5 as i}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"73. Assertions and Defensive Programming","description":"The Little Book of C — 73. Assertions and Defensive Programming","frontmatter":{"title":"73. Assertions and Defensive Programming","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Debugging Testing Profiling"],"description":"The Little Book of C — 73. Assertions and Defensive Programming","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":73,"sidebarWeight":73,"lang":"en-US","alternateEn":"/posts/c教程/en-US/08-Debugging Testing Profiling/073-Assertions and Defensive Programming","alternateZh":"/posts/c教程/zh-CN/08-调试测试与 profiling/073-Assertions and Defensive Programming"},"headers":[],"relativePath":"posts/c教程/en-US/08-Debugging Testing Profiling/073-Assertions and Defensive Programming.md","filePath":"posts/c教程/en-US/08-Debugging Testing Profiling/073-Assertions and Defensive Programming.md","lastUpdated":1790163617000}'),t={name:"posts/c教程/en-US/08-Debugging Testing Profiling/073-Assertions and Defensive Programming.md"};function p(o,s,l,r,c,d){return n(),e("div",null,[...s[0]||(s[0]=[i(`<p>[中文版本](/posts/c教程/zh-CN/08-调试测试与 profiling/073-Assertions and Defensive Programming)</p><p>Bugs are inevitable, but crashes don’t have to be. C gives you direct power over the machine, which means you must protect your own assumptions. That’s where assertions and defensive programming come in: they help you catch mistakes early, fail fast, and make your code predictable.</p><h4 id="step-1-what-is-an-assertion" tabindex="-1">Step 1. What Is an Assertion? <a class="header-anchor" href="#step-1-what-is-an-assertion" aria-label="Permalink to &quot;Step 1. What Is an Assertion?&quot;">​</a></h4><p>An assertion is a sanity check built into your code. It tests whether something you believe to be true actually is. If not, the program immediately stops with an error message, before things get worse.</p><p>Include the header:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;assert.h&gt;</span></span></code></pre></div><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int divide(int a, int b) {</span></span>
<span class="line"><span>    assert(b != 0);  // ensure no division by zero</span></span>
<span class="line"><span>    return a / b;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>If<code>b</code> is zero, the program aborts:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Assertion failed: (b != 0), function divide, file main.c, line 3.</span></span></code></pre></div><h4 id="step-2-how-assertions-work" tabindex="-1">Step 2. How Assertions Work <a class="header-anchor" href="#step-2-how-assertions-work" aria-label="Permalink to &quot;Step 2. How Assertions Work&quot;">​</a></h4><p><code>assert(expression)</code> expands to something like:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if (!(expression)) {</span></span>
<span class="line"><span>    fprintf(stderr, &quot;Assertion failed: %s, file %s, line %d\\n&quot;,</span></span>
<span class="line"><span>            &quot;expression&quot;, __FILE__, __LINE__);</span></span>
<span class="line"><span>    abort();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>When compiled normally, it checks the condition. When compiled with<code>-DNDEBUG</code>, assertions are disabled.</p><h4 id="step-3-enabling-or-disabling-assertions" tabindex="-1">Step 3. Enabling or Disabling Assertions <a class="header-anchor" href="#step-3-enabling-or-disabling-assertions" aria-label="Permalink to &quot;Step 3. Enabling or Disabling Assertions&quot;">​</a></h4><p>Default: assertions are active. To disable them (for production builds):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -DNDEBUG program.c -o program</span></span></code></pre></div><p>In that build,<code>assert()</code> statements are removed.</p><p>This lets you keep your debug checks without slowing down release binaries.</p><h4 id="step-4-practical-example" tabindex="-1">Step 4. Practical Example <a class="header-anchor" href="#step-4-practical-example" aria-label="Permalink to &quot;Step 4. Practical Example&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;assert.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int find_max(int *arr, int n) {</span></span>
<span class="line"><span>    assert(arr != NULL);</span></span>
<span class="line"><span>    assert(n &gt; 0);</span></span>
<span class="line"><span>    int max = arr[0];</span></span>
<span class="line"><span>    for (int i = 1; i &lt; n; i++)</span></span>
<span class="line"><span>        if (arr[i] &gt; max) max = arr[i];</span></span>
<span class="line"><span>    return max;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int data[] = {3, 5, 7, 2, 8};</span></span>
<span class="line"><span>    printf(&quot;Max: %d\\n&quot;, find_max(data, 5));</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>If you pass a<code>NULL</code> pointer or invalid length, the program fails immediately.</p><h4 id="step-5-writing-good-assertions" tabindex="-1">Step 5. Writing Good Assertions <a class="header-anchor" href="#step-5-writing-good-assertions" aria-label="Permalink to &quot;Step 5. Writing Good Assertions&quot;">​</a></h4><p>Assertions should test internal assumptions, not user input. Bad:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assert(argc == 3);</span></span></code></pre></div><p>Good:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if (argc != 3) {</span></span>
<span class="line"><span>    fprintf(stderr, &quot;Usage: %s input output\\n&quot;, argv[0]);</span></span>
<span class="line"><span>    return 1;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Use assertions to check invariants inside your logic, things that should never happen unless there’s a bug.</p><h4 id="step-6-defensive-programming-techniques" tabindex="-1">Step 6. Defensive Programming Techniques <a class="header-anchor" href="#step-6-defensive-programming-techniques" aria-label="Permalink to &quot;Step 6. Defensive Programming Techniques&quot;">​</a></h4><p>Defensive programming goes beyond assertions, it’s about writing code that assumes mistakes will happen.</p><p>Check every function return value:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FILE *f = fopen(&quot;file.txt&quot;, &quot;r&quot;);</span></span>
<span class="line"><span>if (!f) {</span></span>
<span class="line"><span>    perror(&quot;fopen&quot;);</span></span>
<span class="line"><span>    return 1;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Validate inputs:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int divide(int a, int b) {</span></span>
<span class="line"><span>    if (b == 0) {</span></span>
<span class="line"><span>        fprintf(stderr, &quot;Division by zero!\\n&quot;);</span></span>
<span class="line"><span>        return 0;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    return a / b;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Avoid undefined behavior:</p><ul><li>Initialize all variables.</li><li>Don’t access freed memory.</li><li>Check array bounds.</li><li>Always match<code>malloc()</code> with<code>free()</code>.</li></ul><h4 id="step-7-assertions-in-complex-systems" tabindex="-1">Step 7. Assertions in Complex Systems <a class="header-anchor" href="#step-7-assertions-in-complex-systems" aria-label="Permalink to &quot;Step 7. Assertions in Complex Systems&quot;">​</a></h4><p>In large programs, assertions act like tripwires to detect when state becomes inconsistent.</p><p>Example: a queue</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;assert.h&gt;</span></span>
<span class="line"><span>void enqueue(int *queue, int *count, int value, int max) {</span></span>
<span class="line"><span>    assert(*count &lt; max);</span></span>
<span class="line"><span>    queue[*count] = value;</span></span>
<span class="line"><span>    (*count)++;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>If something goes wrong in your logic, the assertion will tell you immediately, before memory corruption happens.</p><h4 id="step-8-logging-vs-assertions" tabindex="-1">Step 8. Logging vs Assertions <a class="header-anchor" href="#step-8-logging-vs-assertions" aria-label="Permalink to &quot;Step 8. Logging vs Assertions&quot;">​</a></h4><ul><li>Assertions: catch programming errors.</li><li>Logging: record runtime information.</li></ul><p>Combine both:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;assert.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int read_value(int *arr, int n, int index) {</span></span>
<span class="line"><span>    assert(index &gt;= 0 &amp;&amp; index &lt; n);</span></span>
<span class="line"><span>    printf(&quot;Reading arr[%d] = %d\\n&quot;, index, arr[index]);</span></span>
<span class="line"><span>    return arr[index];</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="step-9-using-static-assert-for-compile-time-checks-c11" tabindex="-1">Step 9. Using static_assert for Compile-Time Checks (C11+) <a class="header-anchor" href="#step-9-using-static-assert-for-compile-time-checks-c11" aria-label="Permalink to &quot;Step 9. Using static_assert for Compile-Time Checks (C11+)&quot;">​</a></h4><p>C11 introduced<code>_Static_assert</code>, which checks conditions during compilation.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;assert.h&gt;</span></span>
<span class="line"><span>_Static_assert(sizeof(int) == 4, &quot;int must be 4 bytes&quot;);</span></span></code></pre></div><p>If the condition fails, the compiler stops with:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>error: static assertion failed: &quot;int must be 4 bytes&quot;</span></span></code></pre></div><p>This is perfect for configuration or architecture assumptions.</p><h4 id="step-10-tiny-code-safe-array-access" tabindex="-1">Step 10. Tiny Code: Safe Array Access <a class="header-anchor" href="#step-10-tiny-code-safe-array-access" aria-label="Permalink to &quot;Step 10. Tiny Code: Safe Array Access&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;assert.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#define MAX 5</span></span>
<span class="line"><span>int safe_get(int arr[], int n, int i) {</span></span>
<span class="line"><span>    assert(i &gt;= 0 &amp;&amp; i &lt; n);</span></span>
<span class="line"><span>    return arr[i];</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int nums[MAX] = {1, 2, 3, 4, 5};</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, safe_get(nums, MAX, 2));  // OK</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, safe_get(nums, MAX, 10)); // triggers assertion</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Assertion failed: (i &gt;= 0 &amp;&amp; i &lt; n), function safe_get, file main.c, line 7.</span></span></code></pre></div><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Assertions and defensive coding make your software:</p><ul><li>Safer, catch bugs early.</li><li>Easier to debug, fail at the source, not later.</li><li>More maintainable, documents assumptions clearly.</li></ul><p>In C, a single bad pointer can crash your system. Assertions are your safety net.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Add assertions to your stack or linked list implementation.</li><li>Write a function that validates all arguments before proceeding.</li><li>Use<code>_Static_assert</code> to check type sizes in a cross-platform program.</li><li>Combine assertions with logging for detailed error reports.</li><li>Run your program with invalid input and see how quickly assertions detect issues.</li></ol><p>Next, you’ll move into unit testing in C, building small, automated tests to ensure every function works exactly as intended.</p>`,62)])])}const g=a(t,[["render",p]]);export{u as __pageData,g as default};
